<?php session_start();require_once '../config/koneksi.php';if(isset($_SESSION['login'])){header('Location: ../dashboard.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$username=trim($_POST['username']??'');$password=$_POST['password']??'';$st=$conn->prepare("SELECT * FROM users WHERE username=? AND status='aktif' LIMIT 1");$st->bind_param('s',$username);$st->execute();$user=$st->get_result()->fetch_assoc();if($user&&password_verify($password,$user['password'])){session_regenerate_id(true);$_SESSION['login']=true;$_SESSION['id_user']=$user['id_user'];$_SESSION['nama']=$user['nama'];$_SESSION['role']=$user['role'];header('Location: ../dashboard.php');exit;}else{$error='Username atau kata sandi tidak sesuai.';}}?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login | Azki Alazhar</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><style>*{box-sizing:border-box}body{min-height:100vh;background:#f3f6fb;display:grid;place-items:center;font-family:system-ui,-apple-system,"Segoe UI",sans-serif;color:#18304f}.login-wrap{width:min(980px,94vw);min-height:570px;background:white;border-radius:24px;overflow:hidden;display:grid;grid-template-columns:1fr 1fr;box-shadow:0 22px 70px #1a365020}.visual{background:linear-gradient(145deg,#142b4a,#245b98);color:white;padding:48px;display:flex;flex-direction:column;justify-content:space-between;position:relative;overflow:hidden}.visual:after{content:"";position:absolute;width:360px;height:360px;border:1px solid #ffffff24;border-radius:50%;right:-100px;bottom:-120px;box-shadow:0 0 0 35px #ffffff08,0 0 0 75px #ffffff06}.seal{width:60px;height:60px;background:#ffffff18;border:1px solid #ffffff28;border-radius:18px;display:grid;place-items:center;font-size:30px}.visual h1{font-size:35px;font-weight:800;line-height:1.15;margin:24px 0 14px}.visual p{color:#d3e2f5;line-height:1.8}.visual small{color:#c1d2e8}.form-side{padding:52px 46px;display:flex;flex-direction:column;justify-content:center}.form-side h2{font-weight:800;font-size:27px}.muted{color:#7b8ba2;font-size:13px}.form-label{font-size:12px;font-weight:700}.form-control{padding:12px;border-radius:10px;border-color:#dbe3ee}.btn-primary{background:#2563eb;border:0;padding:12px;border-radius:10px;font-weight:700}.input-group-text{background:white;border-color:#dbe3ee;color:#718096}@media(max-width:700px){.login-wrap{grid-template-columns:1fr}.visual{display:none}.form-side{padding:36px 25px;min-height:500px}}</style></head><body><div class="login-wrap"><div class="visual"><div><div class="seal"><i class="bi bi-mortarboard-fill"></i></div><h1>AZKI<br>ALAZHAR</h1><p>Sistem Informasi Administrasi Tata Usaha berbasis web untuk mendukung pengelolaan data sekolah yang lebih rapi, cepat, dan terintegrasi.</p></div><small><i class="bi bi-shield-check me-2"></i>Akses khusus petugas administrasi</small></div><div class="form-side"><div class="mb-4"><div class="muted mb-2">SELAMAT DATANG</div><h2>Masuk ke sistem</h2><p class="muted">Gunakan akun yang telah terdaftar untuk melanjutkan.</p></div><?php if($error):?><div class="alert alert-danger py-2"><?= htmlspecialchars($error,ENT_QUOTES,'UTF-8') ?></div><?php endif;?><form method="post"><div class="mb-3"><label class="form-label">Username</label><div class="input-group"><span class="input-group-text"><i class="bi bi-person"></i></span><input class="form-control" name="username" autocomplete="username" placeholder="Masukkan username" required></div></div><div class="mb-4"><label class="form-label">Kata Sandi</label><div class="input-group"><span class="input-group-text"><i class="bi bi-lock"></i></span><input class="form-control" type="password" name="password" autocomplete="current-password" placeholder="Masukkan kata sandi" required></div></div><button class="btn btn-primary w-100" type="submit">Masuk <i class="bi bi-arrow-right ms-2"></i></button></form><p class="muted text-center mt-4 mb-0">MTs Azki Alazhar · Administrasi Tata Usaha</p></div></div></body></html>